{
  "metric": "trips",
  "target_window": "2024-11-28",
  "baseline_window": "2024-11-07, 2024-11-14, 2024-11-21",
  "hypotheses": [
    {
      "id": "H0",
      "kind": "metric",
      "statement": "Yellow taxi trips on Thursday 2024-11-28 dropped significantly compared to the average of the three prior Thursdays in November 2024 (2024-11-07, 2024-11-14, 2024-11-21).",
      "support_if": "Target day trips are >15% below baseline average.",
      "refute_if": "Target day trips are within ±5% of baseline average."
    },
    {
      "id": "H1",
      "kind": "holiday",
      "statement": "Thanksgiving Day (2024-11-28) is a federal holiday that suppresses commuter and business travel, causing a large trip count drop versus regular Thursdays.",
      "support_if": "us_holidays confirms 2024-11-28 is a national holiday (Thanksgiving) and baseline Thursdays are not holidays.",
      "refute_if": "2024-11-28 is not flagged as a holiday or baseline days are also holidays."
    },
    {
      "id": "H2",
      "kind": "weather",
      "statement": "Adverse weather (precipitation, snow, or extreme cold) on 2024-11-28 reduced demand relative to the prior Thursdays.",
      "support_if": "2024-11-28 shows measurable prcp_mm/snow_mm or tmax_c well below baseline Thursdays' averages.",
      "refute_if": "Weather on 2024-11-28 is similar to or better than baseline Thursdays."
    },
    {
      "id": "H3",
      "kind": "data_quality",
      "statement": "The drop is an artifact of missing or incomplete trip data for 2024-11-28 (e.g., partial day load, vendor outage).",
      "support_if": "Trip count is implausibly low (e.g., near zero) or avg_total_amount/avg_trip_distance are null/outlier vs. baseline.",
      "refute_if": "All metrics for 2024-11-28 are present and within plausible ranges."
    },
    {
      "id": "H4",
      "kind": "fare_mix",
      "statement": "A shift in fare mix (e.g., fewer short/high-volume trips, more long/low-volume trips) on the holiday makes the trip count drop look larger than the underlying demand change.",
      "support_if": "avg_trip_distance on 2024-11-28 is materially higher than baseline while avg_total_amount per mile is lower, indicating mix shift.",
      "refute_if": "avg_trip_distance and avg_total_amount on 2024-11-28 are in line with baseline Thursdays."
    },
    {
      "id": "H5",
      "kind": "zone_mix",
      "statement": "Trip origins/destinations shifted away from high-density zones (e.g., Manhattan core) on the holiday, reducing total trip volume even if per-zone demand was stable.",
      "support_if": "Not directly testable with daily aggregates; would require zone-level data. Kept as a placeholder for future drill-down.",
      "refute_if": "N/A with current daily tables."
    }
  ],
  "queries": [
    {
      "hypothesis_id": "H0",
      "purpose": "Return trips for target day 2024-11-28 and each baseline Thursday (2024-11-07, 2024-11-14, 2024-11-21), plus baseline average, to quantify the drop.",
      "tables": [
        "whybot.yellow_daily"
      ]
    },
    {
      "hypothesis_id": "H1",
      "purpose": "Confirm 2024-11-28 is a federal holiday (Thanksgiving) and that baseline Thursdays are not holidays.",
      "tables": [
        "whybot.us_holidays"
      ]
    },
    {
      "hypothesis_id": "H2",
      "purpose": "Get daily weather (prcp_mm, snow_mm, tmax_c, tmin_c) for 2024-11-28 and the three baseline Thursdays to compare conditions.",
      "tables": [
        "whybot.nyc_weather_daily"
      ]
    },
    {
      "hypothesis_id": "H3",
      "purpose": "Check data quality for 2024-11-28: trips, avg_total_amount, avg_trip_distance vs. baseline Thursdays; flag nulls or extreme outliers.",
      "tables": [
        "whybot.yellow_daily"
      ]
    },
    {
      "hypothesis_id": "H4",
      "purpose": "Compare avg_trip_distance and avg_total_amount on 2024-11-28 vs. baseline Thursdays to detect fare/distance mix shifts.",
      "tables": [
        "whybot.yellow_daily"
      ]
    }
  ],
  "rationale": "Thanksgiving is a known major holiday; the primary hypothesis is holiday suppression (H1). Weather (H2) and data quality (H3) are standard alternative explanations. Fare mix (H4) checks whether the trip count drop is amplified by composition changes. Zone mix (H5) is noted but not queryable with daily aggregates. Baseline uses the three prior Thursdays in November for a like-for-like weekday comparison."
}

{
  "sql": "SELECT y.trip_date, w.prcp_mm, w.snow_mm, w.tmax_c, w.tmin_c, h.holiday_name, d.d_day_name FROM whybot.yellow_daily y JOIN whybot.nyc_weather_daily w ON w.obs_date = y.trip_date LEFT JOIN whybot.us_holidays h ON h.holiday_date = y.trip_date JOIN TPCDS_DB.date_dim d ON d.d_date = y.trip_date WHERE y.trip_date BETWEEN DATE '2024-11-01' AND DATE '2024-11-30' AND d.d_dow = 4 ORDER BY y.trip_date",
  "tables_used": ["whybot.yellow_daily", "whybot.nyc_weather_daily", "whybot.us_holidays", "TPCDS_DB.date_dim"],
  "note": "Baseline Thursdays in November 2024 (d_dow=4) plus 2024-11-28 for weather comparison"
}

