{
  "sql": "SELECT y.trip_date, y.trips, d.d_day_name, h.holiday_name FROM whybot.yellow_daily y JOIN TPCDS_DB.date_dim d ON d.d_date = y.trip_date LEFT JOIN whybot.us_holidays h ON h.holiday_date = y.trip_date WHERE y.trip_date BETWEEN DATE '2024-11-01' AND DATE '2024-11-30' ORDER BY y.trip_date",
  "tables_used": ["whybot.yellow_daily", "TPCDS_DB.date_dim", "whybot.us_holidays"],
  "note": "Joins yellow_daily to date_dim for weekday name and to us_holidays for holiday status; filters to November 2024 to examine Thursday 28 Nov 2024 drop."
}

